const { useState } = React;

function ThemeButton({ theme, onThemeChange }) {
  return <button type="button" onClick={onThemeChange}>{theme === 'dark' ? '밝게' : '어둡게'}</button>;
}
function Section({ theme, onThemeChange }) { return <ThemeButton theme={theme} onThemeChange={onThemeChange} />; }
function Page({ theme, onThemeChange }) { return <section className={theme}><Section theme={theme} onThemeChange={onThemeChange} /></section>; }

function App() {
  const [theme, setTheme] = useState('light');
  return <Page theme={theme} onThemeChange={() => setTheme(theme === 'light' ? 'dark' : 'light')} />;
}

ReactDOM.createRoot(document.querySelector('#root')).render(<App />);

